package com.teamchat.messaging.controller;

import com.teamchat.messaging.dto.ChatMessageDto;
import com.teamchat.messaging.repository.ReactiveChannelMembershipRepository;
import com.teamchat.messaging.repository.ReactiveMessageRepository;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Flux;

@RestController
@RequestMapping("/chat/channels")
public class ChatHistoryController {

    private final ReactiveMessageRepository messageRepository;
    private final ReactiveChannelMembershipRepository membershipRepository;

    public ChatHistoryController(ReactiveMessageRepository messageRepository, ReactiveChannelMembershipRepository membershipRepository) {
        this.messageRepository = messageRepository;
        this.membershipRepository = membershipRepository;
    }

    @GetMapping("/{channelId}/messages")
    public Flux<ChatMessageDto> getChannelMessageHistory(
            @PathVariable String channelId,
            Authentication authentication) {
        return membershipRepository.existsByChannelIdAndUsername(channelId, authentication.getName())
                .flatMapMany(isMember -> {
                    if (!isMember) {
                        return Flux.error(new AccessDeniedException("User is not a member of channel " + channelId));
                    }
                    return messageRepository.findAllByChannelIdOrderByTimestampDesc(channelId)
                            .take(50)
                            .map(msg -> new ChatMessageDto(msg.getId(), msg.getSender(), msg.getContent(), msg.getTimestamp()));
                });
    }
}
